import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"ABI and runtime support","description":"","frontmatter":{"navigation":{"category":"Plugin API"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/abi-and-runtime.md"},"headers":[],"relativePath":"guides/plugin-api/abi-and-runtime.md","filePath":"docs/plugin-api/abi-and-runtime.md","lastUpdated":1792029775000}`),a={name:`guides/plugin-api/abi-and-runtime.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="abi-and-runtime-support" tabindex="-1">ABI and runtime support <a class="header-anchor" href="#abi-and-runtime-support" aria-label="Permalink to “ABI and runtime support”">​</a></h1><p>The npm package version identifies the TypeScript facade release. The WIT package version identifies the host ABI. Package <code>@pumpkin-plugins/pumpkin-api</code> <code>0.1.0</code> carries <code>pumpkin:plugin@0.1.0</code>, aligned with the Pumpkin release pinned in <a href="../../tools/test-harness/src/pumpkin-version.ts"><code>pumpkin-version.ts</code></a>.</p><p>The API package includes <code>wit.lock.json</code>, which pins the upstream WIT commit. The build tool fetches that immutable commit into the consumer project&#39;s ignored <code>.cache/pumpkin-api-wit/&lt;lock-digest&gt;/</code> directory on first use and whenever the lock changes, then generates guest declarations from the fetched source. Keep the package&#39;s WIT ABI and <code>tools/test-harness/src/pumpkin-version.ts</code> aligned when upgrading the pinned server.</p><p>QuickJS and Static Hermes do not have identical runtime internals. The <a href="./../../tools/static-hermes-runtime/docs/">Static Hermes Runtime guide</a> documents current support, conformance status and the pinned host&#39;s custom AI-goal limitation. Do not infer that another operation is supported by Static Hermes solely because it appears in generated declarations or has a generated adapter.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};